  tool(id,x){return `<div class="portal-slot" data-portal-tool="${id}" data-portal-instance="${x}">${renderTool(id,{mode:'portal',instance:x})}</div>`}
  scenarios(){let all=this.module.scenarios||[];if(!all.length)return this.next('quiz','Continue to knowledge check');let i=Math.min(this.state.scenarioIndex,all.length-1),done=all.every(x=>this.state.completed[`scenario-${x.id}`]);if(done||this.state.scenarioSummary)return this.scenarioSummaryView(all);let x=all[i];return this.scenarioStep(x,i,all.length)}
  scenarioStep(x,i,total){let ans=this.state.scenarioAnswers[x.id],att=(this.state.scenarioAttempts[x.id]||[]),firstTry=att.length===1&&att[0]===x.correctAnswer,hints=this.state.scenarioHints[x.id]||0,answered=!!ans;return`<section><p class="eyebrow">Scenario ${i+1} of ${total}</p><h1>${this.esc(x.title)}</h1><p class="lead">${this.esc(x.content)}</p>${x.redFlags?`<ul class="red-flag-list"><li class="eyebrow">Red flags you may notice</li>${x.redFlags.map(r=>`<li>${this.icon('flag','w-4 h-4')}${this.esc(r)}</li>`).join('')}</ul>`:''}<article class="scenario-card"><div class="decision-options">${(x.choices||[]).map(c=>`<button class="decision-btn ${ans===c.text?'selected':''} ${answered?(c.correct?'safe':'unsafe'):''}" data-scenario-pick="${this.esc(c.text)}" ${answered?'disabled':''}>${this.esc(c.text)}</button>`).join('')}</div>${answered?this.scenarioFeedback(x,ans,firstTry,hints):''}</article>${answered?`<div class="scenario-navigation">${hints>0?`<span class="hint-count">${hints} hint${hints>1?'s':''} used</span>`:''}${i<total-1?`<button class="primary-btn" data-scenario-next>Next scenario ${this.icon('arrow-right','w-4 h-4')}</button>`:`<button class="primary-btn" data-scenario-summary>See your results ${this.icon('arrow-right','w-4 h-4')}</button>`}</div>`:x.choices&&x.choices.length&&!answered?`<div class="scenario-navigation"><button class="text-btn" data-scenario-hint>Use a hint</button></div>`:''}<div class="scenario-progress"><i><b style="width:${Math.round((i+1)/total*100)}%"></b></i><span>${i+1} / ${total}</span></div></section>`}
  scenarioFeedback(x,ans,firstTry,hints){let c=(x.choices||[]).find(o=>o.text===ans),best=(x.choices||[]).find(o=>o.correct),ok=!!c&&c.correct;return`<div class="feedback ${ok?'success':'warning'}"><div>${this.icon(ok?'circle-check':'circle-alert','w-5 h-5')}<strong>${ok?(firstTry?'Safe choice on the first try':'Safe choice — after '+hints+' hint'+(hints>1?'s':'')):'What would happen in real life'}</strong>${c?`<p>${this.esc(c.consequence||x.action||x.impact||x.lesson||'')}</p>`:''}${!ok&&best?`<div class="safer-choice"><p class="eyebrow">The safer choice</p><strong>${this.esc(best.text)}</strong><p>${this.esc(best.consequence||'')}</p></div>`:''}${x.lesson?`<small class="lesson-line">${this.icon('lightbulb','w-4 h-4')}${this.esc(x.lesson)}</small>`:''}</div></div>`}
  scenarioSummaryView(all){let safe=all.filter(x=>{let a=this.state.scenarioAttempts[x.id]||[];return a.length===1&&a[0]===x.correctAnswer}).length,avg=all.length?Math.round(safe/all.length*100):0;this.state.scenarioSummary=true;this.persist();return`<section class="wrapup-view"><div class="completion-mark">${this.icon('shield-check','w-10 h-10')}</div><p class="eyebrow">Scenario room · results</p><h1>${safe} of ${all.length} scenarios answered safely on first try</h1><p class="lead">${avg>=75?'Strong judgement across this module.':'Review the consequences below to sharpen your instinct for next time.'}</p><div class="stats-grid"><div class="stat-card"><p>Safe on first try</p><strong>${safe}/${all.length}</strong></div><div class="stat-card"><p>First-try success rate</p><strong>${avg}%</strong></div><div class="stat-card"><p>Module scenario score</p><strong>${this.scenarioScore()}%</strong></div></div><div class="scenario-review-stack">${all.map(x=>{let a=this.state.scenarioAttempts[x.id]||[],ok=a.length===1&&a[0]===x.correctAnswer,best=(x.choices||[]).find(c=>c.correct);return`<article class="scenario-review ${ok?'safe':'missed'}"><div>${this.icon(ok?'circle-check':'circle-alert','w-5 h-5')}</div><div><h3>${this.esc(x.title)}</h3><p>${this.esc(x.content)}</p>${best?`<p class="best-choice">${this.icon('shield-check','w-4 h-4')}Safer choice: <strong>${this.esc(best.text)}</strong></p>`:''}</div></article>`}).join('')}</div><div class="scenario-navigation"><button class="secondary-btn" data-scenario-retry>Retry scenarios</button>${this.next('quiz','Continue to knowledge check')}</div></section>`}
  quiz(){let q=this.module.quiz||[];if(!q.length)return this.next('reflection','Continue to reflection');let i=Math.min(this.state.quizIndex,q.length-1),x=q[i],a=this.state.quizAnswers[x.id];if(this.state.quizSubmitted)return `<section><p class="eyebrow">Assessment complete</p><h1>Quiz score: ${this.quizScore()}%</h1><p class="lead">Review each explanation or retry to improve your score.</p>${q.map((z,n)=>`<article class="activity-card"><h2>${n+1}. ${this.esc(z.question)}</h2>${this.feedback(this.state.quizAnswers[z.id]===z.correctAnswer,z.explanation)}</article>`).join('')}<button class="secondary-btn" data-retry>Retry quiz</button>${this.next('reflection','Continue to reflection')}</section>`;return `<section><p class="eyebrow">Knowledge check</p><h1>Question ${i+1} of ${q.length}</h1><p class="lead">Select an answer, then move through the quiz.</p><article class="activity-card"><h2>${this.esc(x.question)}</h2><div class="decision-options">${(x.options||[]).map(o=>`<button class="decision-btn ${a===o?'selected':''}" data-quiz-answer="${x.id}" data-answer="${this.esc(o)}">${this.esc(o)}</button>`).join('')}</div></article><div class="quiz-navigation"><button class="secondary-btn" data-quiz-prev ${i?'':'disabled'}>Previous</button>${i<q.length-1?`<button class="primary-btn" data-quiz-next ${a?'':'disabled'}>Next</button>`:`<button class="primary-btn" data-quiz-submit ${a?'':'disabled'}>Submit quiz</button>`}</div></section>`}
